export type ContentStatus = "draft" | "review" | "published";
export interface ContentDraft {
  id?: string;
  title: string;
  slug: string;
  summary: string;
  body: string;
  category: string;
  status: ContentStatus;
}
export interface ContentRecord extends ContentDraft {
  id: string;
  updated: string;
}
export type ContentErrors = Partial<
  Record<"title" | "slug" | "summary" | "body" | "category" | "status", string>
>;
export interface ContentEditor01Props {
  modelValue: ContentDraft;
  categories?: readonly string[];
  errors?: ContentErrors;
  pending?: boolean;
  dirty?: boolean;
  message?: string;
  showBack?: boolean;
  allowPreview?: boolean;
}
export const contentCategories = ["Guides", "Stories", "Updates"] as const;
export const contentStatuses: readonly ContentStatus[] = [
  "draft",
  "review",
  "published",
];
export const statusLabels: Record<ContentStatus, string> = {
  draft: "Draft",
  review: "In review",
  published: "Published",
};
export function contentSlug(title: string) {
  return title
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80)
    .replace(/-$/g, "");
}
export function contentWordCount(value: string) {
  return value.trim().split(/\s+/).filter(Boolean).length;
}
export function prepareContentDraft(
  draft: ContentDraft,
  categories: readonly string[],
  records: readonly ContentRecord[] = [],
) {
  const value = {
    ...draft,
    title: draft.title.trim(),
    slug: draft.slug.trim(),
    summary: draft.summary.trim(),
    body: draft.body.trim(),
  };
  const errors: ContentErrors = {};
  if (value.title.length < 3 || value.title.length > 120)
    errors.title = "Use a title between 3 and 120 characters.";
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value.slug) || value.slug.length > 80)
    errors.slug =
      "Use lowercase letters, numbers, and single hyphens (up to 80 characters).";
  else if (
    records.some(
      (record) => record.id !== value.id && record.slug === value.slug,
    )
  )
    errors.slug = "Another entry already uses this slug.";
  if (value.summary.length > 280)
    errors.summary = "Keep the summary within 280 characters.";
  if (value.body.length > 20000)
    errors.body = "Keep the body within 20,000 characters.";
  else if (value.status !== "draft" && !value.body)
    errors.body = "Add body text before sending this entry beyond draft.";
  if (!categories.includes(value.category))
    errors.category = "Choose a current category.";
  if (!contentStatuses.includes(value.status))
    errors.status = "Choose a supported status.";
  return { value, errors, valid: Object.keys(errors).length === 0 };
}
export function equalContent(a: ContentDraft, b: ContentDraft) {
  return ["id", "title", "slug", "summary", "body", "category", "status"].every(
    (key) => a[key as keyof ContentDraft] === b[key as keyof ContentDraft],
  );
}
export function blankContent(): ContentDraft {
  return {
    title: "",
    slug: "",
    summary: "",
    body: "",
    category: contentCategories[0],
    status: "draft",
  };
}
export const sampleContent: readonly ContentRecord[] = [
  {
    id: "calmer",
    title: "Designing a calmer digital workspace",
