.contenteditor01 {
  --contenteditor01-column-gap: var(--space-6);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.contenteditor01 *,
.contenteditor01 *::before,
.contenteditor01 *::after {
  box-sizing: border-box;
}
.contenteditor01 :is(h1, h2, h3, p) {
  margin: 0;
}
.contenteditor01 .contenteditor01-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-6);
}
.contenteditor01-kicker {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.contenteditor01 .contenteditor01-heading h1 {
  margin-block: var(--space-3);
  font-size: var(--font-size-3xl);
  line-height: var(--typography-heading-lineheight);
  letter-spacing: var(--typography-heading-letterspacing);
}
.contenteditor01-heading .text {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
}
.contenteditor01-columns {
  display: flex;
  align-items: start;
  gap: var(--contenteditor01-column-gap);
}
.contenteditor01-writing {
  flex: 1 1 70%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}
.contenteditor01-side {
  flex: 1 1 30%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  position: sticky;
  top: var(--space-6);
}
.contenteditor01-panel {
  padding: var(--space-6);
  border: var(--border-width-thin) solid var(--card-border);
  border-radius: var(--card-radius);
  background: var(--card-background);
  box-shadow: var(--card-shadow);
}
.contenteditor01-panel > * + * {
  margin-block-start: var(--space-5);
}
.contenteditor01-panel-heading {
  display: flex;
  gap: var(--space-4);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.contenteditor01-panel-heading > span {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: start;
  flex-shrink: 0;
  width: var(--space-8);
  height: var(--space-8);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--form-radius);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.contenteditor01-panel h2 {
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-semibold);
}
.contenteditor01-panel-heading .text {
  font-size: var(--font-size-xs);
  margin-block-start: var(--space-2);
  color: var(--text-muted);
}
.contenteditor01 .form-field {
  min-width: 0;
}
.contenteditor01 .form-field > .text {
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
}
.contenteditor01 :is(.input, .select, .textarea) {
  width: 100%;
  min-width: 0;
}
.contenteditor01 textarea[name="body"] {
  line-height: var(--line-height-relaxed);
  resize: vertical;
}
.contenteditor01-hint {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
}
.contenteditor01-preview-note {
  padding: var(--space-5);
  border: var(--border-width-thin) dashed var(--border-strong);
  border-radius: var(--card-radius);
}
.contenteditor01-preview-note h3 {
  margin-block: var(--space-4) var(--space-3);
  font-size: var(--font-size-lg);
  overflow-wrap: anywhere;
}
.contenteditor01-preview-note .text {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
  overflow-wrap: anywhere;
}
.contenteditor01-preview-note > span {
  display: block;
  margin-block-start: var(--space-5);
  color: var(--text-muted);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  overflow-wrap: anywhere;
}
.contenteditor01 .contenteditor01-actions {
  position: sticky;
  bottom: 0;
  gap: var(--space-4);
  padding: var(--space-4) var(--space-5);
  margin-block-start: var(--space-5);
  background: var(--surface-card);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-sm);
  z-index: var(--z-base);
}
.contenteditor01-actions p {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
@media (max-width: 900px) {
  .contenteditor01-columns {
    flex-direction: column;
  }
  .contenteditor01-writing,
  .contenteditor01-side {
    width: 100%;
    flex-basis: auto;
  }
  .contenteditor01-side {
    position: static;
    flex-direction: row;
  }
  .contenteditor01-side > * {
    flex: 1 1 50%;
    min-width: 0;
  }
}
@media (max-width: 600px) {
  .contenteditor01-panel {
    padding: var(--space-4);
  }
  .contenteditor01-side {
    flex-direction: column;
  }
  .contenteditor01 .contenteditor01-actions {
    padding: var(--space-4);
  }
}
